"""Adapter to convert OpenHands trajectories to the project's Trajectory/Step format.

OpenHands uses OpenAI function-calling API format:
  - system/user/assistant/tool roles
  - assistant messages have content (thinking) + tool_calls (structured)
  - tool messages have content (output) + tool_call_id

We convert to the same flat text format used by SWE-agent data:
  - system/user/ai roles
  - ai messages have thinking + ```command``` blocks
  - user messages have observation text
"""

from __future__ import annotations

import json
import re
from dataclasses import dataclass, field
from typing import Optional


@dataclass
class Step:
    index: int
    role: str  # "system", "user", or "ai"
    text: str
    mask: bool = False
    cutoff_date: Optional[str] = None
    system_prompt: Optional[str] = None

    @property
    def is_action(self) -> bool:
        return self.role == "ai"

    @property
    def is_observation(self) -> bool:
        return self.role == "user" and self.index > 0

    @property
    def is_system(self) -> bool:
        return self.role == "system"

    @property
    def command(self) -> Optional[str]:
        if self.role != "ai":
            return None
        match = re.search(r"```\n?(.*?)```", self.text, re.DOTALL)
        if match:
            return match.group(1).strip()
        return None

    @property
    def has_file_display(self) -> bool:
        return "[File:" in self.text

    @property
    def has_error(self) -> bool:
        return "Traceback" in self.text or "Error" in self.text

    @property
    def has_test_output(self) -> bool:
        return ("PASSED" in self.text or "FAILED" in self.text) and "test" in self.text.lower()


@dataclass
class Trajectory:
    instance_id: str
    model_name: str
    target: bool
    steps: list[Step]
    exit_status: str
    generated_patch: Optional[str]
    eval_logs: Optional[str]
    row_index: int = 0

    @property
    def num_steps(self) -> int:
        return len(self.steps)

    @property
    def actions(self) -> list[Step]:
        return [s for s in self.steps if s.is_action]

    @property
    def observations(self) -> list[Step]:
        return [s for s in self.steps if s.is_observation]

    @property
    def issue_text(self) -> Optional[str]:
        if len(self.steps) > 1 and self.steps[1].role == "user":
            return self.steps[1].text
        return None

    @property
    def has_patch(self) -> bool:
        return bool(self.generated_patch and self.generated_patch.strip())


def _format_tool_call(tc: dict) -> str:
    """Format a single OpenHands tool_call into a SWE-agent-style command string."""
    fn = tc.get("function", {})
    name = fn.get("name", "unknown")
    args_str = fn.get("arguments", "")

    try:
        args = json.loads(args_str)
    except (json.JSONDecodeError, TypeError):
        args = {"raw": args_str}

    if name == "execute_bash":
        cmd = args.get("command", args_str)
        return cmd
    elif name == "str_replace_editor":
        command = args.get("command", "view")
        path = args.get("path", "")
        parts = [f"{command} {path}"]
        if command == "str_replace":
            old = args.get("old_str", "")
            new = args.get("new_str", "")
            parts.append(f"old_str:\n{old}")
            parts.append(f"new_str:\n{new}")
        elif command == "insert":
            line = args.get("insert_line", "")
            text = args.get("new_str", "")
            parts.append(f"insert_line: {line}")
            parts.append(f"new_str:\n{text}")
        elif command == "view":
            vr = args.get("view_range")
            if vr:
                parts[0] += f" [{vr}]"
        elif command == "create":
            text = args.get("file_text", "")
            parts.append(f"file_text:\n{text[:500]}")
        return "\n".join(parts)
    elif name == "think":
        return f"think: {args.get('thought', args_str)}"
    else:
        flat_args = " ".join(f"{k}={repr(v)[:100]}" for k, v in args.items()) if isinstance(args, dict) else str(args)
        return f"{name} {flat_args}"


def convert_openhands_message(msg: dict) -> tuple[str, str]:
    """Convert a single OpenHands message to (role, text) in our format.

    Returns:
        (role, text) where role is "system", "user", or "ai"
    """
    oh_role = msg.get("role", "")
    content = msg.get("content") or ""
    tool_calls = msg.get("tool_calls") or []

    if oh_role == "system":
        return "system", content

    if oh_role == "user":
        return "user", content

    if oh_role == "assistant":
        parts = []
        if content:
            parts.append(content)
        for tc in tool_calls:
            cmd_text = _format_tool_call(tc)
            parts.append(f"```\n{cmd_text}\n```")
        return "ai", "\n\n".join(parts) if parts else content

    if oh_role == "tool":
        return "user", content

    return "user", content


def convert_openhands_trajectory(raw: dict, row_index: int = 0) -> Trajectory:
    """Convert a raw OpenHands record dict to our Trajectory format.

    Args:
        raw: Dict with keys from the OpenHands parquet: trajectory_id, instance_id,
             trajectory (list of message dicts), exit_status, resolved, model_patch.
        row_index: Source file line number.
    """
    oh_traj = raw.get("trajectory") or []
    steps = []
    for i, msg in enumerate(oh_traj):
        role, text = convert_openhands_message(msg)
        steps.append(Step(
            index=i,
            role=role,
            text=text,
            mask=False,
            system_prompt=text if role == "system" and i == 0 else None,
        ))

    resolved = raw.get("resolved", 0)
    target = bool(resolved) if isinstance(resolved, (int, float)) else False

    return Trajectory(
        instance_id=raw.get("instance_id", ""),
        model_name="openhands",
        target=target,
        steps=steps,
        exit_status=raw.get("exit_status", ""),
        generated_patch=raw.get("model_patch"),
        eval_logs=None,
        row_index=row_index,
    )


def convert_trajectory_to_serializable(traj: Trajectory) -> dict:
    """Convert to the same JSONL format used by SWE-agent data_loader."""
    steps_out = []
    for s in traj.steps:
        d = {"role": s.role, "text": s.text, "mask": s.mask}
        if s.cutoff_date:
            d["cutoff_date"] = s.cutoff_date
        if s.system_prompt:
            d["system_prompt"] = s.system_prompt
        steps_out.append(d)

    return {
        "instance_id": traj.instance_id,
        "model_name": traj.model_name,
        "target": traj.target,
        "trajectory": steps_out,
        "exit_status": traj.exit_status,
        "generated_patch": traj.generated_patch,
        "eval_logs": traj.eval_logs,
    }


